/* CSS PART 1 OF 4 */

/* =========================================
   JOSH BROOKS CONSTRUCTION & RENOVATION
   PART 1 — DESIGN TOKENS & FOUNDATIONS
   ========================================= */

/* 01. DESIGN TOKENS */

:root {
  color-scheme: light;

  /* Brand-inspired color palette */
  --color-ink: #202a32;
  --color-ink-soft: #35434d;
  --color-slate: #53636c;
  --color-muted: #78858b;

  --color-primary: #a95e36;
  --color-primary-dark: #874626;
  --color-primary-light: #d18b5f;

  --color-background: #f6f5f1;
  --color-surface: #ffffff;
  --color-surface-alt: #ecebe5;
  --color-border: #deded7;

  --color-text: #28343b;
  --color-text-light: #69757b;
  --color-white: #ffffff;

  --color-focus: #1769aa;

  /* Typography */
  --font-heading: "Montserrat", "Arial", sans-serif;
  --font-body: "Inter", "Helvetica Neue", sans-serif;

  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.375rem;
  --font-size-2xl: 1.875rem;
  --font-size-3xl: 2.5rem;
  --font-size-4xl: clamp(2.75rem, 5.5vw, 5rem);

  --line-height-tight: 1.08;
  --line-height-heading: 1.2;
  --line-height-body: 1.7;

  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;
  --font-weight-heavy: 800;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --container-width: 1200px;
  --container-wide: 1440px;
  --container-padding: clamp(1.25rem, 5vw, 4rem);

  --header-height: 84px;
  --section-spacing: clamp(4.5rem, 9vw, 8rem);

  /* Borders and corners */
  --border-width: 1px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 14px;
  --radius-pill: 999px;

  /* Shadows */
  --shadow-subtle: 0 4px 16px rgba(32, 42, 50, 0.06);
  --shadow-card: 0 12px 35px rgba(32, 42, 50, 0.09);
  --shadow-strong: 0 20px 55px rgba(20, 29, 35, 0.17);

  /* Transitions */
  --transition-fast: 180ms ease;
  --transition-standard: 280ms ease;
  --transition-slow: 450ms ease;

  /* Layering */
  --z-base: 1;
  --z-header: 100;
  --z-overlay: 200;
  --z-modal: 300;
}


/* =========================================
   02. RESET & GLOBAL NORMALIZATION
   ========================================= */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-height) + 1rem);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-width: 320px;
  margin: 0;
  background: var(--color-background);
  color: var(--color-text);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-regular);
  line-height: var(--line-height-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img,
picture,
video,
canvas,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

ul,
ol {
  margin: 0;
  padding: 0;
}

p,
h1,
h2,
h3,
h4,
h5,
h6 {
  margin-top: 0;
}

p {
  margin-bottom: 1.25rem;
}

p:last-child {
  margin-bottom: 0;
}

::selection {
  background: var(--color-primary);
  color: var(--color-white);
}


/* =========================================
   03. TYPOGRAPHY SYSTEM
   ========================================= */

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.045em;
  line-height: var(--line-height-heading);
}

h1 {
  font-size: var(--font-size-4xl);
  font-weight: var(--font-weight-heavy);
  line-height: var(--line-height-tight);
}

h2 {
  font-size: clamp(2rem, 3.8vw, 3.25rem);
  line-height: 1.12;
}

h3 {
  font-size: clamp(1.25rem, 2vw, 1.65rem);
}

h4 {
  font-size: var(--font-size-lg);
}

p {
  color: var(--color-text-light);
}

strong,
b {
  color: var(--color-ink);
  font-weight: var(--font-weight-semibold);
}

small {
  font-size: var(--font-size-sm);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  margin-bottom: var(--space-5);
  color: var(--color-primary);
  font-family: var(--font-heading);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.15em;
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 760px;
  margin-bottom: var(--space-6);
}

.section-intro {
  max-width: 650px;
  font-size: var(--font-size-lg);
  line-height: 1.8;
}

.text-accent {
  color: var(--color-primary);
}

.text-light {
  color: var(--color-white);
}

.text-muted {
  color: var(--color-muted);
}


/* =========================================
   04. PAGE GRID & SHARED CONTAINERS
   ========================================= */

.container {
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
}

.container-wide {
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-wide)
  );
  margin-inline: auto;
}

.container-narrow {
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    800px
  );
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: var(--section-spacing);
}

.section--compact {
  padding-block: clamp(3rem, 6vw, 5rem);
}

.section--dark {
  background: var(--color-ink);
  color: var(--color-white);
}

.section--dark h2,
.section--dark h3,
.section--dark h4,
.section--dark strong {
  color: var(--color-white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.75);
}

.section--light {
  background: var(--color-surface);
}

.section--muted {
  background: var(--color-surface-alt);
}

.grid {
  display: grid;
  gap: var(--space-8);
}

.grid--two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid--three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid--four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.flex {
  display: flex;
}

.flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.align-center {
  align-items: center;
}

.text-center {
  text-align: center;
}

.text-left {
  text-align: left;
}

.stack > * + * {
  margin-top: var(--space-4);
}


/* =========================================
   05. ACCESSIBILITY FOUNDATIONS
   ========================================= */

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 4px;
}

a,
button,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}

.skip-link {
  position: absolute;
  z-index: var(--z-modal);
  top: 0;
  left: 1rem;
  padding: 0.85rem 1.25rem;
  transform: translateY(-150%);
  border-radius: var(--radius-sm);
  background: var(--color-ink);
  color: var(--color-white);
  font-weight: var(--font-weight-semibold);
  transition: transform var(--transition-fast);
}

.skip-link:focus {
  transform: translateY(1rem);
}

[hidden] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* =========================================
   06. RESPONSIVE GRID FOUNDATIONS
   ========================================= */

@media (max-width: 900px) {
  :root {
    --header-height: 72px;
  }

  .grid--four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid--three {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  :root {
    --container-padding: 1.25rem;
    --section-spacing: 4.5rem;
  }

  body {
    font-size: 0.95rem;
  }

  .grid--two,
  .grid--three,
  .grid--four {
    grid-template-columns: minmax(0, 1fr);
  }

  .section-heading {
    margin-bottom: var(--space-5);
  }

  .section-intro {
    font-size: var(--font-size-base);
  }

  .text-center-mobile {
    text-align: center;
  }
}
