/* CSS PART 2 OF 4 */

/* =========================================
   JOSH BROOKS CONSTRUCTION & RENOVATION
   PART 2 — HEADER, NAVIGATION & HERO
   ========================================= */


/* 01. SITE HEADER */

.site-header {
  position: sticky;
  z-index: var(--z-header);
  top: 0;
  width: 100%;
  min-height: var(--header-height);
  background: rgba(255, 255, 255, 0.97);
  border-bottom: 1px solid var(--color-border);
  box-shadow: 0 3px 18px rgba(32, 42, 50, 0.045);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.header-inner {
  display: flex;
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-wide)
  );
  min-height: var(--header-height);
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.site-brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.85rem;
  color: var(--color-ink);
}

.site-brand img {
  width: auto;
  max-width: 190px;
  max-height: 62px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  line-height: 1.15;
}

.brand-name {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 0.92rem;
  font-weight: var(--font-weight-heavy);
  letter-spacing: -0.035em;
}

.brand-description {
  color: var(--color-muted);
  font-size: 0.63rem;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.105em;
  text-transform: uppercase;
}


/* 02. DESKTOP NAVIGATION */

.primary-navigation {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 2vw, 1.85rem);
}

.primary-navigation ul {
  display: flex;
  align-items: center;
  gap: clamp(0.9rem, 1.6vw, 1.5rem);
  list-style: none;
}

.primary-navigation a:not(.button) {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--color-ink-soft);
  font-family: var(--font-heading);
  font-size: 0.76rem;
  font-weight: var(--font-weight-semibold);
  transition: color var(--transition-fast);
}

.primary-navigation a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--color-primary);
  content: "";
  transition: transform var(--transition-standard);
}

.primary-navigation a:not(.button):hover,
.primary-navigation a:not(.button):focus-visible {
  color: var(--color-primary-dark);
}

.primary-navigation a:not(.button):hover::after,
.primary-navigation a:not(.button):focus-visible::after {
  transform: scaleX(1);
}


/* 03. HEADER CONTACT ACTION */

.header-actions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--space-4);
}

.header-phone {
  display: flex;
  flex-direction: column;
  line-height: 1.35;
}

.header-phone-label {
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.header-phone a {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 0.88rem;
  font-weight: var(--font-weight-bold);
  white-space: nowrap;
  transition: color var(--transition-fast);
}

.header-phone a:hover {
  color: var(--color-primary);
}


/* 04. SHARED BUTTON SYSTEM */

.button {
  display: inline-flex;
  min-height: 52px;
  padding: 0.9rem 1.55rem;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--color-primary);
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 0.82rem;
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.015em;
  line-height: 1.3;
  text-align: center;
  transition:
    background var(--transition-standard),
    color var(--transition-standard),
    border-color var(--transition-standard),
    box-shadow var(--transition-standard),
    transform var(--transition-standard);
}

.button:hover {
  transform: translateY(-2px);
  background: var(--color-primary-dark);
  box-shadow: 0 8px 20px rgba(135, 70, 38, 0.2);
  color: var(--color-white);
}

.button:active {
  transform: translateY(0);
}

.button--primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.button--secondary {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--color-white);
}

.button--secondary:hover {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-ink);
}

.button--dark {
  background: var(--color-ink);
  color: var(--color-white);
}

.button--dark:hover {
  background: var(--color-ink-soft);
}

.button--outline {
  border-color: var(--color-border);
  background: transparent;
  color: var(--color-ink);
}

.button--outline:hover {
  border-color: var(--color-primary);
  background: var(--color-primary);
  color: var(--color-white);
}

.button--small {
  min-height: 44px;
  padding: 0.7rem 1.15rem;
  font-size: 0.75rem;
}

.button--large {
  min-height: 58px;
  padding: 1rem 1.9rem;
  font-size: 0.88rem;
}


/* 05. MOBILE NAVIGATION TOGGLE */

.nav-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-white);
  color: var(--color-ink);
}

.nav-toggle span {
  display: block;
  width: 19px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transition:
    transform var(--transition-standard),
    opacity var(--transition-standard);
}

.nav-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(7px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-7px) rotate(-45deg);
}


/* 06. HERO SECTION */

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - var(--header-height)));
  overflow: hidden;
  align-items: center;
  isolation: isolate;
  background: var(--color-ink);
  color: var(--color-white);
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background-image:
    linear-gradient(
      90deg,
      rgba(20, 29, 35, 0.94) 0%,
      rgba(20, 29, 35, 0.84) 38%,
      rgba(20, 29, 35, 0.42) 72%,
      rgba(20, 29, 35, 0.19) 100%
    ),
    url("https://joshbrooksconstructionllc.com/wp-content/uploads/2026/09/finished-roof-ridge-thornton-co-768x1024.jpg");
  background-position: center, center 44%;
  background-repeat: no-repeat;
  background-size: cover;
  content: "";
}

.hero::after {
  position: absolute;
  z-index: -1;
  right: 0;
  bottom: 0;
  left: 0;
  height: 9px;
  background: var(--color-primary);
  content: "";
}

.hero-inner {
  display: grid;
  width: min(
    calc(100% - (var(--container-padding) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
  padding-block: clamp(5rem, 10vw, 9rem);
  grid-template-columns: minmax(0, 1fr);
}

.hero-content {
  max-width: 760px;
}

.hero .eyebrow {
  color: #e8a779;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: var(--space-6);
  color: var(--color-white);
  font-size: var(--font-size-4xl);
  line-height: 1.06;
  letter-spacing: -0.055em;
}

.hero h1 span {
  color: #e8a779;
}

.hero-description {
  max-width: 620px;
  margin-bottom: var(--space-8);
  color: rgba(255, 255, 255, 0.84);
  font-size: clamp(1rem, 1.6vw, 1.2rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-4);
}

.hero-actions .button--primary {
  background: var(--color-primary);
}

.hero-actions .button--primary:hover {
  background: var(--color-primary-dark);
}

.hero-contact-note {
  display: flex;
  margin-top: var(--space-6);
  align-items: center;
  gap: 0.65rem;
  color: rgba(255, 255, 255, 0.76);
  font-size: var(--font-size-sm);
}

.hero-contact-note a {
  color: var(--color-white);
  font-weight: var(--font-weight-bold);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.5);
  text-underline-offset: 4px;
}

.hero-contact-note a:hover {
  color: #e8a779;
}


/* 07. HERO TRUST STRIP */

.hero-trust {
  display: flex;
  margin-top: var(--space-10);
  padding-top: var(--space-6);
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-6);
  border-top: 1px solid rgba(255, 255, 255, 0.24);
}

.hero-trust-item {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.hero-trust-value {
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 0.88rem;
  font-weight: var(--font-weight-bold);
}

.hero-trust-label {
  color: rgba(255, 255, 255, 0.67);
  font-size: 0.7rem;
  letter-spacing: 0.045em;
}


/* 08. HERO IMAGE ACCENT */

.hero-image-accent {
  position: absolute;
  right: max(3vw, calc((100vw - var(--container-wide)) / 2));
  bottom: 4rem;
  width: min(210px, 17vw);
  aspect-ratio: 3 / 4;
  overflow: hidden;
  border: 5px solid rgba(255, 255, 255, 0.9);
  box-shadow: var(--shadow-strong);
}

.hero-image-accent img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}


/* 09. RESPONSIVE HEADER & HERO */

@media (max-width: 1100px) {
  .primary-navigation ul {
    gap: 0.85rem;
  }

  .primary-navigation a:not(.button) {
    font-size: 0.7rem;
  }

  .brand-description {
    display: none;
  }

  .header-phone {
    display: none;
  }
}

@media (max-width: 900px) {
  .header-inner {
    position: relative;
  }

  .nav-toggle {
    display: flex;
    flex-shrink: 0;
  }

  .primary-navigation {
    position: absolute;
    top: 100%;
    right: calc(var(--container-padding) * -1);
    left: calc(var(--container-padding) * -1);
    display: none;
    padding: 1rem var(--container-padding) 1.5rem;
    align-items: stretch;
    flex-direction: column;
    gap: 1rem;
    border-top: 1px solid var(--color-border);
    border-bottom: 1px solid var(--color-border);
    background: var(--color-white);
    box-shadow: var(--shadow-card);
  }

  .primary-navigation.is-open {
    display: flex;
  }

  .primary-navigation ul {
    align-items: stretch;
    flex-direction: column;
    gap: 0;
  }

  .primary-navigation a:not(.button) {
    width: 100%;
    min-height: 48px;
    padding-block: 0.6rem;
    border-bottom: 1px solid var(--color-border);
    font-size: 0.88rem;
  }

  .primary-navigation a:not(.button)::after {
    display: none;
  }

